style.css:
@-moz-document domain("roblox.com") {
html::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: url("https://i.pinimg.com/736x/7c/8d/91/7c8d91164342905080f0530b8b67d82a.jpg") no-repeat center center fixed;
        background-size: cover;
        z-index: -1;
        pointer-events: none;
    }

    body,
    #container-main,
    .content,
    .section,
    .page-content {
        background: transparent !important;
    }
}
